insert into public.team_roles (key, label, description, sort) values
('owner', 'Owner', 'Full access, including owners and billing settings. Mapped from the suhail-owners group.', 1),
('admin', 'Admin', 'Everything except changing owners. Mapped from the suhail-admins group.', 2),
('member', 'Team', 'Reads and writes all dashboard work. Mapped from the suhail-team group.', 3)
insert into public.forms (key, name_en, name_ar, stages, schema) values
('careers', 'Careers', 'الوظائف في سهيل', '["New","Reviewing","Task review","Interview","Offer","Joined","Not now"]'::jsonb, null),
('hack', 'Hackathon applications', 'طلبات الهاكاثون', '["New","Reviewing","Accepted","Waitlist","Not now"]'::jsonb, '{"coll":"hack_apps","submit":["Apply","قدّم"],"fields":[[{"id":"name","en":"Name","ar":"الاسم","type":"text","req":1},{"id":"email","en":"Email","ar":"البريد الإلكتروني","type":"email","req":1}],{"id":"event","en":"Which hackathon","ar":"أي هاكاثون","type":"select","req":1,"opts":"@hackathons"},{"id":"role","en":"You are mainly","ar":"تخصصك الأساسي","type":"radio","req":1,"opts":[["Engineer","Engineer","مهندس"],["Designer","Designer","مصمّم"],["Researcher","Researcher","باحث"],["Product","Product","منتج"]]},[{"id":"stack","en":"Stack and skills","ar":"التقنيات والمهارات","type":"text"},{"id":"github","en":"GitHub or portfolio","ar":"GitHub أو معرض أعمال","type":"text","ltr":1}],{"id":"team","en":"Team","ar":"الفريق","type":"radio","req":1,"opts":[["solo","Solo, match me","لحالي، لقوا لي فريق"],["team","I have a team","عندي فريق"]]},{"id":"idea","en":"What would you build?","ar":"وش تبي تبني؟","type":"textarea"}]}'::jsonb),
('house', 'Al Freej applications', 'طلبات الفريج', '["New","Reviewing","Call","Trial week","Moved in","Not now"]'::jsonb, '{"coll":"house_apps","submit":["Apply","قدّم"],"fields":[[{"id":"name","en":"Name","ar":"الاسم","type":"text","req":1},{"id":"email","en":"Email","ar":"البريد الإلكتروني","type":"email","req":1}],[{"id":"company","en":"Company or project","ar":"الشركة أو المشروع","type":"text"},{"id":"country","en":"Based in","ar":"مقيم في","type":"select","opts":"@countries"}],{"id":"stage","en":"Stage","ar":"المرحلة","type":"radio","req":1,"opts":[["idea","Before the idea","قبل الفكرة"],["building","Building","نبني"],["users","Have users","عندنا مستخدمين"],["revenue","Have revenue","عندنا إيرادات"]]},{"id":"fulltime","en":"Full-time on it?","ar":"متفرّغ لها؟","type":"radio","req":1,"opts":[["yes","Yes","إيه"],["when","When I move in","لما أدخل البيت"],["no","Not yet","للحين لا"]]},{"id":"built","en":"Link to something you built","ar":"رابط لشي بنيته","type":"text","req":1,"ltr":1},{"id":"why","en":"What will you build in the house?","ar":"وش بتبني في البيت؟","type":"textarea","req":1}]}'::jsonb),
('talent', 'Talent pool', 'قائمة المواهب', '["New","Reviewing","Contacted","Done","Not now"]'::jsonb, '{"coll":"talent","submit":["Join the pool","انضم"],"fields":[[{"id":"name","en":"Name","ar":"الاسم","type":"text","req":1},{"id":"email","en":"Email","ar":"البريد الإلكتروني","type":"email","req":1}],{"id":"track","en":"Track","ar":"المسار","type":"radio","req":1,"opts":[["tech","Technical","تقنية"],["ops","Ops & Business","عمليات وأعمال"]]},{"id":"level","en":"Seniority","ar":"الخبرة","type":"radio","opts":[["junior","0–2 years","0–2 سنة"],["mid","3–6 years","3–6 سنوات"],["senior","7+ years","7 سنوات وأكثر"]]},[{"id":"cities","en":"Cities you''d work in","ar":"المدن اللي تشتغل فيها","type":"text"},{"id":"link","en":"LinkedIn, GitHub or site","ar":"LinkedIn أو GitHub أو موقعك","type":"text","ltr":1}],{"id":"next","en":"What do you want next?","ar":"وش تبي تسوي بعدين؟","type":"textarea"}]}'::jsonb),
('cofounder', 'Co-founder matching', 'الشركاء المؤسّسون', '["New","Reviewing","Contacted","Done","Not now"]'::jsonb, '{"coll":"cofounders","submit":["Send","أرسل"],"fields":[[{"id":"name","en":"Name","ar":"الاسم","type":"text","req":1},{"id":"email","en":"Email","ar":"البريد الإلكتروني","type":"email","req":1}],{"id":"bring","en":"You bring","ar":"أنت تجيب","type":"radio","req":1,"opts":[["tech","Technical","الجانب التقني"],["biz","Business","جانب الأعمال"],["design","Design and product","التصميم والمنتج"]]},{"id":"need","en":"You''re looking for","ar":"تدوّر على","type":"radio","req":1,"opts":[["tech","Technical","تقني"],["biz","Business","أعمال"],["design","Design and product","تصميم ومنتج"]]},{"id":"idea","en":"The idea, or the space","ar":"الفكرة أو المجال","type":"textarea"},{"id":"link","en":"Link to you","ar":"رابط لك","type":"text","ltr":1}]}'::jsonb),
('company', 'Companies', 'الشركات', '["New","Reviewing","Contacted","Done","Not now"]'::jsonb, '{"coll":"companies","submit":["Submit","أرسل"],"fields":[[{"id":"company","en":"Company","ar":"الشركة","type":"text","req":1},{"id":"site","en":"Website","ar":"الموقع","type":"text","ltr":1}],[{"id":"name","en":"Your name","ar":"اسمك","type":"text","req":1},{"id":"email","en":"Work email","ar":"بريد العمل","type":"email","req":1}],{"id":"stage","en":"Stage","ar":"المرحلة","type":"radio","opts":[["Early","Early","مبكرة"],["Growth","Growth","نمو"],["Scaling","Scaling","توسّع"],["Large","Large","شركة كبيرة"]]},[{"id":"city","en":"Main office","ar":"المكتب الرئيسي","type":"text"},{"id":"count","en":"Open roles","ar":"عدد الوظائف","type":"text"}],{"id":"roles","en":"Which roles?","ar":"وش الوظائف؟","type":"textarea"}]}'::jsonb),
('season', 'Season', 'الموسم', '["New","Reviewing","Contacted","Done","Not now"]'::jsonb, '{"coll":"season","submit":["Send","أرسل"],"fields":[[{"id":"name","en":"Name","ar":"الاسم","type":"text","req":1},{"id":"email","en":"Email","ar":"البريد الإلكتروني","type":"email","req":1}],[{"id":"company","en":"Company","ar":"الشركة","type":"text"},{"id":"title","en":"Role","ar":"المسمّى","type":"text"}],{"id":"as","en":"I want to","ar":"أبي","type":"radio","req":1,"opts":[["attend","Attend","أحضر"],["speak","Speak","أتكلّم"],["workshop","Run a workshop","أقدّم ورشة"]]},{"id":"talk","en":"If speaking: the talk in one line","ar":"إذا بتتكلّم: الفكرة بسطر واحد","type":"textarea"}]}'::jsonb),
('partner', 'Partners', 'الشركاء', '["New","Reviewing","Contacted","Done","Not now"]'::jsonb, '{"coll":"partners","submit":["Send","أرسل"],"fields":[[{"id":"company","en":"Company","ar":"الشركة","type":"text","req":1},{"id":"name","en":"Your name","ar":"اسمك","type":"text","req":1}],[{"id":"email","en":"Work email","ar":"بريد العمل","type":"email","req":1},{"id":"title","en":"Role","ar":"المسمّى","type":"text"}],{"id":"goal","en":"You''re after","ar":"تبي","type":"checks","req":1,"opts":[["talent","Talent","مواهب"],["distribution","Distribution","انتشار"],["community","Community","مجتمع"]]},{"id":"note","en":"Anything we should know","ar":"شي لازم نعرفه","type":"textarea"}]}'::jsonb),
('podcast', 'Podcast', 'البودكاست', '["New","Reviewing","Contacted","Done","Not now"]'::jsonb, '{"coll":"podcast","submit":["Send","أرسل"],"fields":[[{"id":"name","en":"Your name","ar":"اسمك","type":"text","req":1},{"id":"email","en":"Email","ar":"البريد الإلكتروني","type":"email","req":1}],{"id":"who","en":"Guest","ar":"الضيف","type":"radio","req":1,"opts":[["me","Me","أنا"],["someone","Someone else","شخص ثاني"]]},{"id":"guest","en":"Guest name and link","ar":"اسم الضيف ورابطه","type":"text","ltr":0},{"id":"why","en":"Why them?","ar":"ليش هو؟","type":"textarea","req":1}]}'::jsonb)
insert into public.roles (slug, title_en, title_ar, plain_en, plain_ar, pitch_en, pitch_ar, do_en, do_ar, you_en, you_ar, form_schema, rubric, sort) values
('partnerships', 'Partnerships', 'الشراكات', 'Head of Partnerships', 'رئيس الشراكات', 'Brings in the investors, companies, universities and cities that back Suhail, and keeps them involved.', 'يجيب المستثمرين والشركات والجامعات والمدن اللي تدعم سهيل، ويخلّيهم جزء منه.', array['Build relationships with investors, companies, universities and government bodies across the region.','Shape partnership formats: hackathon tracks, recruiting, the newsletter and Suhail Season.','Secure the partners for the first events, and keep them for the next ones.']::text[], array['تبني علاقات مع المستثمرين والشركات والجامعات والجهات الحكومية في المنطقة.','تصمّم صيغ الشراكة: مسارات الهاكاثون، والتوظيف، والنشرة، وموسم سهيل.','تأمّن شركاء أول الفعاليات، وتحافظ عليهم للي بعدها.']::text[], array['You have a real network in the region''s startup ecosystem.','You''re good at closing, and better at following up.','You''re at ease in Arabic and English.']::text[], array['عندك شبكة حقيقية في منظومة الشركات الناشئة بالمنطقة.','تعرف تقفل الاتفاق، وتعرف تتابع بعده أكثر.','مرتاح بالعربي والإنجليزي.']::text[], '[{"id":"task_h","en":"Your turn","ar":"دورك","type":"head"},{"id":"p_pitch","en":"Pick a real company in the region that should sponsor our first hackathon. Write them the message you''d send.","ar":"اختر شركة حقيقية في المنطقة لازم ترعى أول هاكاثون لنا، واكتب لهم الرسالة اللي بترسلها.","type":"textarea","req":1,"max":150,"note":["Who it''s to, what you ask for (with a number), and why they''d say yes.","لمين، وش تطلب منهم (برقم)، وليش بيوافقون."]},{"id":"p_deal","en":"A deal or partnership you closed. What did they want, what did you give, what came out of it?","ar":"اتفاقية أو شراكة قفلتها. وش كانوا يبون، وش عطيتهم، ووش طلع منها؟","type":"textarea","req":1,"max":120},{"id":"p_calls","en":"Who could you get on a call this month? Roles and companies, not names.","ar":"مين تقدر تكلّمه هالشهر؟ المنصب والشركة، مو الأسماء.","type":"textarea","req":1,"max":60,"ph":"Head of Developer Relations at …"},{"id":"p_markets","en":"Where your network is strongest","ar":"وين شبكة علاقاتك أقوى","type":"checks","opts":"@countries"}]'::jsonb, '[{"key":"ask","en":"Clear ask with a real number"},{"key":"market","en":"Knows the regional market"},{"key":"yes","en":"Would they say yes?"}]'::jsonb, 1),
('events', 'Events and Programming', 'الفعاليات والبرامج', 'Head of Events and Programming', 'رئيس الفعاليات والبرامج', 'Plans and runs everything people come to: hackathons, firesides, The Majlis podcast and Suhail Season.', 'يخطّط ويدير كل شي يحضره الناس: الهاكاثونات، والجلسات الحوارية، وبودكاست المجلس، وموسم سهيل.', array['Plan and run hackathons, fireside chats and Suhail Season, from the venue to the last demo.','Produce The Majlis podcast: pick guests, plan episodes and run recordings.','Own the calendar: what happens, where, when and with which partners.']::text[], array['تخطّط وتدير الهاكاثونات والجلسات الحوارية وموسم سهيل، من المكان لآخر عرض.','تنتج بودكاست المجلس: تختار الضيوف، وتجهّز الحلقات، وتدير التسجيل.','تمسك التقويم: وش يصير، ووين، ومتى، ومع أي شركاء.']::text[], array['You''ve organised events, talks or a podcast before.','You care about details and stay calm when things break.','You can be in the room for events in the region.']::text[], array['نظّمت فعاليات أو جلسات أو بودكاست قبل.','تهتم بالتفاصيل، وهادي لما يخرب شي.','تقدر تكون حاضر في فعاليات المنطقة.']::text[], '[{"id":"task_h","en":"Your turn","ar":"دورك","type":"head"},{"id":"e_design","en":"Design our first hackathon in five lines: city, theme, partners, prize, and the one moment people will remember.","ar":"صمّم أول هاكاثون لنا في خمس سطور: المدينة، الموضوع، الشركاء، الجائزة، واللحظة اللي الناس بتتذكرها.","type":"textarea","req":1,"max":120},{"id":"e_majlis","en":"Three guests for The Majlis podcast, and the one question you''d ask each.","ar":"ثلاث ضيوف لبودكاست المجلس، وسؤال واحد بتسأله لكل واحد.","type":"textarea","req":1,"max":120},{"id":"e_fire","en":"It''s 7am on demo day and the venue has no internet. What do you do in the first hour?","ar":"الساعة ٧ الصبح يوم العروض، والمكان ما فيه إنترنت. وش تسوي في أول ساعة؟","type":"textarea","req":1,"max":100},{"id":"e_past","en":"An event, talk or podcast you ran: how many people, your role, a link if there is one.","ar":"فعالية أو جلسة أو بودكاست نظّمته: كم شخص، دورك، ورابط إذا موجود.","type":"textarea","req":1,"max":100}]'::jsonb, '[{"key":"design","en":"A hackathon people would remember"},{"key":"calm","en":"Calm under pressure"},{"key":"guests","en":"Guests worth listening to"}]'::jsonb, 2),
('editorial', 'Editorial', 'التحرير', 'Head of Editorial', 'رئيس التحرير', 'Finds the promising startups and the news worth knowing, and tells their story in the newsletter and on social.', 'يلقى الشركات الناشئة الواعدة والأخبار اللي تستاهل، ويحكي قصتها في النشرة وعلى المنصّات.', array['Scout promising startups and founders across the region before they''re on anyone''s list.','Write the weekly newsletter and decide what''s worth people''s time.','Turn firesides, podcast episodes and news into posts, clips and threads.']::text[], array['تلقى الشركات الناشئة والمؤسّسين الواعدين في المنطقة قبل ما يكونون على قائمة أحد.','تكتب النشرة الأسبوعية، وتقرّر وش يستاهل وقت الناس.','تحوّل الجلسات وحلقات البودكاست والأخبار لمنشورات ومقاطع وسلاسل.']::text[], array['You follow tech in the region closely, from the source.','You write clearly in Arabic and English.','You know a good story when you see one.']::text[], array['تتابع التقنية في المنطقة عن قرب، ومن مصادرها الأولى.','تكتب بوضوح بالعربي والإنجليزي.','تعرف القصة الحلوة أول ما تشوفها.']::text[], '[{"id":"task_h","en":"Your turn","ar":"دورك","type":"head"},{"id":"w_open","en":"Write the opening of our first newsletter: one thing that happened in the region''s tech this month, and why it matters.","ar":"اكتب افتتاحية أول نشرة لنا: شي صار في تقنية المنطقة هالشهر، وليش يهم.","type":"textarea","req":1,"max":150,"note":["Write it in Arabic or English, whichever is stronger for you.","اكتبها بالعربي أو الإنجليزي، اللي تكون فيه أقوى."]},{"id":"w_scout","en":"A founder or startup in the region nobody is talking about yet. Who, and why they matter.","ar":"مؤسّس أو شركة ناشئة في المنطقة محد يتكلّم عنها للحين. مين، وليش تهم.","type":"textarea","req":1,"max":100},{"id":"w_sources","en":"Three things you read or follow every week that most people don''t","ar":"ثلاث أشياء تقراها أو تتابعها كل أسبوع وأغلب الناس ما يعرفونها","type":"textarea","req":1,"max":60},{"id":"w_samples","en":"Links to things you''ve written","ar":"روابط لأشياء كتبتها","type":"textarea","req":1,"ltr":1,"ph":"https://…"}]'::jsonb, '[{"key":"writing","en":"Clear writing"},{"key":"scouting","en":"Finds what others miss"},{"key":"judgement","en":"Knows what''s worth people''s time"}]'::jsonb, 3),
('engineering', 'Engineering and Research', 'الهندسة والأبحاث', 'Head of Engineering', 'رئيس الهندسة', 'Leads Suhail''s open research: foundation models, datasets and benchmarks built for the Arab world and released in the open.', 'يقود أبحاث سهيل المفتوحة: نماذج أساسية وبيانات ومعايير مبنية للعالم العربي ومنشورة للكل.', array['Pick the first projects and turn them into a research roadmap: models the region needs that nobody has built yet.','Fine-tune and adapt open-weight models on regional data, and publish the weights, code and results.','Build open datasets and benchmarks with the community, universities and partners, and lead the people who contribute to them.']::text[], array['تختار أول المشاريع وتحوّلها لخطة أبحاث: نماذج تحتاجها المنطقة وما بناها أحد للحين.','تدرّب وتكيّف نماذج مفتوحة الأوزان على بيانات المنطقة، وتنشر الأوزان والكود والنتائج.','تبني بيانات ومعايير مفتوحة مع المجتمع والجامعات والشركاء، وتقود الناس اللي يساهمون فيها.']::text[], array['You''ve trained or fine-tuned models and shipped the results, in a lab, a company or on your own.','You care about data quality and honest evaluation as much as the model.','You can get a lot done with little compute, and you know how to find more.']::text[], array['درّبت أو كيّفت نماذج ونشرت النتائج، في مختبر أو شركة أو لحالك.','تهتم بجودة البيانات والتقييم الصادق بقدر اهتمامك بالنموذج.','تعرف تنجز كثير بموارد حوسبة قليلة، وتعرف كيف تلقى أكثر.']::text[], '[{"id":"task_h","en":"Your turn","ar":"دورك","type":"head"},{"id":"g_plan","en":"You get 8 GPUs for a month and no budget for new data. Which open model or dataset for the Arab world do you build, from what, and how will you know it''s good?","ar":"عندك ٨ معالجات رسومية لمدة شهر وما فيه ميزانية لبيانات جديدة. أي نموذج أو مجموعة بيانات مفتوحة للعالم العربي بتبني، من وين، وكيف بتعرف إنه زين؟","type":"textarea","req":1,"max":200},{"id":"g_number","en":"Something you trained, fine-tuned or evaluated, and the number that told you it worked","ar":"شي درّبته أو كيّفته أو قيّمته، والرقم اللي قال لك إنه نجح","type":"textarea","req":1,"max":100},{"id":"g_broken","en":"An Arabic AI benchmark or dataset you think is broken, and why","ar":"معيار أو مجموعة بيانات عربية للذكاء الاصطناعي تشوفها خربانة، وليش","type":"textarea","max":100},{"id":"g_profiles","en":"GitHub, Hugging Face or Google Scholar","ar":"GitHub أو Hugging Face أو Google Scholar","type":"text","req":1,"ltr":1,"ph":"https://"}]'::jsonb, '[{"key":"plan","en":"A plan that fits the compute"},{"key":"evidence","en":"Measures honestly"},{"key":"shipped","en":"Has shipped models or data"}]'::jsonb, 4),
('finance', 'Finance', 'المالية', 'Finance Lead', 'مسؤول المالية', 'Runs Suhail''s money: budgets, the books, partner deals and the path to revenue.', 'يدير فلوس سهيل: الميزانيات، والحسابات، واتفاقيات الشركاء، والطريق للدخل.', array['Build the budgets for every event and for the year, and track where every dirham goes.','Set up the company side: entity, banking, invoicing and partner contracts across the region.','Model how Suhail makes money, from sponsorships and tickets to partnerships, and get us to the point where these roles are paid.']::text[], array['تبني ميزانية كل فعالية وميزانية السنة، وتتابع وين يروح كل درهم.','تجهّز الجانب الرسمي: الكيان، والحسابات البنكية، والفواتير، وعقود الشركاء في المنطقة.','تبني نموذج دخل سهيل، من الرعايات والتذاكر للشراكات، وتوصلنا لليوم اللي تصير فيه هذي الأدوار مدفوعة.']::text[], array['You''ve worked in finance, accounting or operations at a startup, a fund or a firm.','You''re careful with numbers and clear when you explain them.','You know how money and companies work in at least one country in the region.']::text[], array['اشتغلت في المالية أو المحاسبة أو العمليات، في شركة ناشئة أو صندوق أو شركة.','دقيق مع الأرقام، وواضح لما تشرحها.','تعرف كيف تمشي الفلوس والشركات في دولة وحدة على الأقل في المنطقة.']::text[], '[{"id":"task_h","en":"Your turn","ar":"دورك","type":"head"},{"id":"f_budget","en":"Our first hackathon: 150 people, one city, two days. Give us a rough budget in a few lines: the biggest costs, and how you''d cover them.","ar":"أول هاكاثون لنا: ١٥٠ شخص، مدينة وحدة، يومين. عطنا ميزانية تقريبية في سطور: أكبر التكاليف، وكيف بتغطيها.","type":"textarea","req":1,"max":150},{"id":"f_revenue","en":"Three ways Suhail could make money in year one, ranked. Which one do you start with, and why?","ar":"ثلاث طرق ممكن سهيل يحقّق فيها دخل في أول سنة، بالترتيب. بأي وحدة تبدأ، وليش؟","type":"textarea","req":1,"max":120},{"id":"f_done","en":"Finance work you''ve done: budgets, books, fundraising or deals","ar":"شغلك في المالية: ميزانيات، حسابات، تمويل أو اتفاقيات","type":"textarea","req":1,"max":100},{"id":"f_setup","en":"Where you know how companies, banking and tax work","ar":"وين تعرف كيف تمشي الشركات والبنوك والضرائب","type":"checks","req":1,"opts":"@countries"}]'::jsonb, '[{"key":"budget","en":"Realistic budget"},{"key":"revenue","en":"Sound revenue thinking"},{"key":"region","en":"Knows how money works here"}]'::jsonb, 5)
insert into public.hackathons (slug, title_en, title_ar, city_en, city_ar, fmt, scene, desc_en, desc_ar, published, sort) values
('agents-online', 'Arabic Agents Hack', 'هاكاثون الوكلاء العرب', 'Online', 'أونلاين', 'online', 'pattern', 'Build agents that work in Arabic, from anywhere. Open to anyone. Challenges and partners are announced to applicants.', 'ابنِ وكلاء يشتغلون بالعربي، من أي مكان. مفتوح للجميع. التحديات والشركاء يُعلنون للمتقدّمين.', false, 1),
('applied-ai-kuwait', 'Applied AI Hack', 'هاكاثون الذكاء التطبيقي', 'Kuwait City', 'الكويت', 'inperson', 'skyline', 'Meet, build and demo in one day. The schedule, challenges and partners below are kept up to date by the event team.', 'تقابل وتبني وتعرض في يوم واحد. البرنامج والتحديات والشركاء يحدّثها فريق الفعالية.', false, 2),
('energy-riyadh', 'Energy and Climate Hack', 'هاكاثون الطاقة والمناخ', 'Riyadh', 'الرياض', 'inperson', 'tent', 'Grids, cooling and water for the hottest places on earth. One day, real data from partners.', 'شبكات وتبريد ومياه لأحرّ أماكن على الأرض. يوم واحد، وبيانات حقيقية من الشركاء.', false, 3),
('physical-cairo', 'Physical AI Hack', 'هاكاثون الذكاء المادي', 'Cairo', 'القاهرة', 'inperson', 'dhow', 'Robots, sensors and machines that leave the screen. Hardware is provided on site.', 'روبوتات وحسّاسات وآلات تطلع من الشاشة. الأجهزة متوفرة في المكان.', false, 4)
